import plistlib,re,os,json
L=os.path.expanduser('~/Library')
SECRET=re.compile(r'key|token|secret|passw|mail|username|uuid|user_?id|licen|credential|auth|session|jwt',re.I)
EMAIL=re.compile(r'[\w.+-]+@[\w-]+\.\w+')
def clean(k,v,depth=0):
    if SECRET.search(str(k)) and v not in ('',None,False,True): return '<redacted>'
    if isinstance(v,bytes):
        try: v=plistlib.loads(v)
        except Exception:
            try: v=json.loads(v)
            except Exception: return f'<{len(v)} bytes>'
    if isinstance(v,str):
        if v[:1] in '{[':
            try: return clean(k,json.loads(v),depth)
            except Exception: pass
        v=EMAIL.sub('<email>',v)
        return v if len(v)<200 else v[:200]+'…'
    if isinstance(v,dict): return {a:clean(a,b,depth+1) for a,b in v.items()}
    if isinstance(v,list):
        out=[clean(k,i,depth+1) for i in v[:60]]
        if len(v)>60: out.append(f'…({len(v)} total)')
        return out
    return v if isinstance(v,(int,float,bool,type(None))) else str(v)
for p in ['Preferences/org.languagetool.desktop.plist','Group Containers/N6PF5J2JR8.org.languagetool.desktop.group/Library/Preferences/N6PF5J2JR8.org.languagetool.desktop.group.plist']:
    f=os.path.join(L,p)
    print('=====',p,os.path.exists(f))
    if os.path.exists(f):
        try: print(json.dumps(clean('',plistlib.load(open(f,'rb'))),indent=1,default=str))
        except Exception as e: print('ERR',e)
EOF
